import csv
OUT='/home/claude/emst/docs/research/field-craft/fieldcraft_proficiency_anchors.csv'
H=['anchor_id','competency_ref','level','observable_behavior','evidence_of_performance','assessment_method','notes']
T='Tolerance is illustrative; set by the program measurement-quality objective. IO to validate.'
R=[
# Vegetation sampling 4.1.1
['FCA-VEG-1','4.1.1','Foundational','Lays out a plot to protocol (monuments, bearings, transects) and records species cover; on a season-start calibration plot, cover estimates for dominant species fall within tolerance of the reference observer, and unknown plants are collected as labelled vouchers rather than guessed.','Calibration-plot score sheet; voucher log; QA re-visit agreement for 1 in N plots','Observer calibration against a reference observer (AIM/FIA-style); supervisor re-visit',T],
['FCA-VEG-2','4.1.1','Intermediate','Identifies most regional vascular plants to species in the field, including common taxa in vegetative or senescent state; when site conditions depart from protocol assumptions (post-fire, flooded, grazed) adapts sampling and records the deviation so data stay comparable.','Blind identification test results across at least two phenological states; deviation notes in the data; hot-check agreement','Blind field ID test across seasons; hot check by crew lead','Testing across phenology avoids single-season bias.'],
['FCA-VEG-3','4.1.1','Advanced','Designs a monitoring layout that meets stated detection or precision objectives within budget, then tests a remote-sensed vegetation or cover product against plot data and explains where and why they disagree.','Sampling design memo with precision rationale; validation table with field-cause annotations','Portfolio review plus field walk-through at disagreement sites','DC co-assesses the statistical parts.'],
['FCA-VEG-4','4.1.1','Expert','Acts as reference observer: calibrates other observers, adjudicates disputed identifications or cover calls with written reasoning, and revises protocol wording where repeated disagreement shows ambiguity; between-observer variance falls in the next calibration.','Calibration statistics before and after; adjudication log; protocol revision record','Review of two seasons of calibration data; peer review by another reference observer','Replaces v1 "Achieves recognition for vegetation monitoring excellence".'],
# Mensuration 1.3.2
['FCA-MEN-1','1.3.2','Foundational','Measures diameter, height, crown and defect on plot trees; independent blind re-measurement agrees within tolerance for the required share of trees and no plot-edge trees are missed or double counted.','QA blind-check report','Independent blind re-measurement (FIA-style blind check)',T],
['FCA-MEN-2','1.3.2','Intermediate','Runs a cruise or inventory crew to a sampling plan; sets plot intensity to reach a stated sampling error; detects and corrects systematic crew errors (height bias, borderline trees) during the season.','Cruise report with achieved sampling error; hot-check notes; correction log','Hot check during work plus office review of achieved precision',''],
['FCA-MEN-3','1.3.2','Advanced','Integrates field plots with lidar or imagery models: specifies where plots are needed for calibration, names stand conditions where remote estimates fail (multi-storied, steep, recently disturbed) and allocates plots accordingly.','Design memo; model-versus-plot validation by stratum','Portfolio plus structured interview at field sites','DC co-assesses model fitting.'],
['FCA-MEN-4','1.3.2','Expert','Sets measurement standards and quality assurance for an inventory program: defines tolerances, runs a cold-check program, adjudicates measurement disputes, and shows program-level agreement improving.','QA program documentation; trend in QA agreement','Program audit',''],
# Species identification 1.4.3 / 4.1.2
['FCA-ID-1','1.4.3|4.1.2','Foundational','Identifies common regional species of the target group by sight, sound or sign under typical field conditions; records "unknown" and collects evidence (photo, recording, voucher) when not certain; blind-test error rate is within program limit.','Practical identification test result; evidence records for unknowns','Station-based or audio practical test (FISC-style)','Scoring rewards correct expressions of uncertainty, not only correct names.'],
['FCA-ID-2','1.4.3|4.1.2','Intermediate','Identifies difficult taxa, life stages and partial sign; recognizes records that are implausible for place or season; confirms or rejects AI-suggested identifications and states the correct reason.','Blind test that includes AI-suggested labels with planted errors; log of rejected implausible records','Blind adjudication test seeded with known AI errors','Directly tests the human role that remains when AI suggests IDs.'],
['FCA-ID-3','1.4.3|FC-C03','Advanced','Serves as verifier for a program\'s automated detections (camera, acoustic, eDNA): sets review-sampling rules, measures false-positive and false-negative rates on a validation set, and directs targeted field confirmation.','Verification protocol; validation statistics; field confirmation results','Portfolio plus audit of a random sample of verified records by another expert','Formation dependency: expertise built in the field even though work is on screen.'],
['FCA-ID-4','1.4.3','Expert','Resolves disputed records for a region or taxon with documented evidence, trains and certifies other identifiers, and maintains reference collections or sound and image libraries used by people and models.','Adjudication records; certification records; reference library contributions','Peer review by a recognized authority; records audit','Reference libraries may involve Indigenous names or knowledge: include only with consent and under TN guidance.'],
# Soil 4.1.4
['FCA-SOIL-1','4.1.4','Foundational','Describes a soil pit in standard terms (horizons, color, texture, structure, coarse fragments) and estimates texture by feel; texture class matches laboratory particle-size results within one class for most samples.','Pit description forms paired with lab results','Paired field-laboratory comparison over a season','Texture by feel is the v1 paradigm human-essential task; this makes it measurable.'],
['FCA-SOIL-2','4.1.4','Intermediate','Identifies diagnostic features (redoximorphic features, restrictive layers, buried horizons) and relates them to hydrology, erosion risk or productivity; moves sampling location or depth to capture site variation.','Descriptions and interpretations checked by a soil scientist','Side-by-side pit evaluation with an assessor',''],
['FCA-SOIL-3','4.1.4','Advanced','Resolves conflicts between soil maps or digital soil products and field evidence; documents inclusions and their management implications.','Field notes versus map unit; written recommendation','Field review with assessor',''],
['FCA-SOIL-4','4.1.4','Expert','Calibrates other describers and sets regional field description conventions; adjudicates disputed classifications.','Calibration workshop agreement statistics; conventions document','Peer review',''],
# Water field sampling 4.1.3 + FC-C16/C24
['FCA-H2O-1','4.1.3|FC-C24','Foundational','Calibrates field meters before use and checks them afterward; collects grab samples with the required clean-handling method; completes labels and chain of custody without error; field blanks show no contamination.','Calibration logs; chain-of-custody forms; blank results','Observed sampling run (field assistance visit) plus QC result review',''],
['FCA-H2O-2','4.1.3|FC-C16','Intermediate','Chooses sampling points and timing that represent the condition of interest (mixing, flow, storm timing); recognizes conditions that invalidate a sample (disturbed sediment, holding-time breach) and resamples or flags.','Site sheets with rationale; flag and resample log','Field evaluation plus review of flagged events',''],
['FCA-H2O-3','4.1.3|FC-C24','Advanced','Plans the field QC design (blanks, duplicates, splits) for a project, traces QC failures to their field cause and changes procedures so they do not recur.','Field sections of a quality assurance project plan; QC investigation report','Audit by the program QA officer',''],
['FCA-H2O-4','4.1.3|FC-C24','Expert','Leads field audits of other crews or organizations against a field sampling standard, writes corrective actions and verifies they took effect.','Audit reports; follow-up verification','Review by an accreditation assessor (e.g., TNI FSMO) or program QA lead',''],
# Chainsaw 4.5.2
['FCA-SAW-1','4.5.2','Foundational','Performs pre-use saw checks, wears full PPE and bucks and limbs downed material in non-complex situations under supervision, keeping safe position and an escape route.','Field evaluation checklist signed by a certified evaluator','Field evaluation (federal saw program style)','Course completion (e.g., S-212) is an input, not this anchor.'],
['FCA-SAW-2','4.5.2','Intermediate','Sizes up and fells trees in moderately complex conditions: reads lean, defects and overhead hazards, plans face cut and hinge, and lands the tree within the planned lay while controlling the work area.','Evaluator scoresheet across several observed fellings','Observed felling evaluation',''],
['FCA-SAW-3','4.5.2','Advanced','Fells complex trees (heavy lean, decay, fire-weakened) or declines and selects an alternative (mechanical, leave, blast) with stated risk reasoning.','Evaluation in complex conditions; recorded decline decisions','Field evaluation plus scenario interview','Declining a tree is evidence of proficiency, not a failure.'],
['FCA-SAW-4','4.5.2','Expert','Evaluates and certifies other sawyers consistently with other evaluators and uses incident reviews to change training.','Evaluator records; inter-evaluator agreement; incident reviews','Evaluator calibration review',''],
# Prescribed fire 4.3.2 / 4.2.3
['FCA-RX-1','4.3.2|4.2.3','Foundational','As a crew member, holds assigned line, keeps lookouts-communications-escape routes-safety zones in place, and reports spots, slopovers and fire-behavior changes promptly and accurately by radio.','Completed position task book tasks; supervisor evaluation','Position task book observation on prescribed fires','Crosswalk to NWCG positions (PMS 310-1).'],
['FCA-RX-2','4.3.2|4.2.3','Intermediate','As firing boss or ignition specialist, sequences hand, drone or aerial ignition to keep fire within prescription; changes pattern as fire behavior and wind change; halts ignition when holding capacity is exceeded.','Task book sign-off; ignition logs; observed fire behavior versus prescription','Task book evaluation on burns with incident-type coding; after-action review','Includes supervising UAS ignition operators, now scaled practice.'],
['FCA-RX-3','4.3.2','Advanced','As burn boss, makes and documents go/no-go decisions against prescription, test-fire results and contingency resources; declares contingency or wildfire when triggers are met.','Burn plan; go/no-go checklist; test-fire record; after-action review','Burn boss task book; review of decisions across several burns including at least one no-go',''],
['FCA-RX-4','4.3.2','Expert','Technically reviews complex burn plans, mentors burn bosses and leads reviews after escapes that lead to documented program changes.','Technical review records; escape reviews; adopted changes','Peer review; program audit','Cultural fire practitioners\' qualifications: TN decides; do not assume NWCG equivalence.'],
# Field risk 4.4.1
['FCA-RISK-1','4.4.1','Foundational','At a new work site, names the actual hazards before starting (overhead, terrain, weather, wildlife, traffic, equipment) and the control for each; calls stop-work when conditions change.','Completed tailgate or JHA record; observed stop-work','Scenario walk-through at a real site',''],
['FCA-RISK-2','4.4.1','Intermediate','Leads a site-specific briefing that addresses that day\'s hazards (not a generic script), assigns lookout and communication roles and revises the plan when hazards change.','Briefing record; assessor observation; crew feedback','Observed briefing scored against site conditions',''],
['FCA-RISK-3','4.4.1|FC-C27','Advanced','Designs controls for unusual or combined hazards (heat with remote access, drones near crews, contaminated material found on site) and runs near-miss learning reviews that identify system causes, not only individual error.','JHA for a complex operation; learning review reports','Portfolio review plus interview',''],
['FCA-RISK-4','4.4.1','Expert','Changes field safety systems (training, equipment, staffing rules) based on learning reviews; repeat incident types decline and near-miss reporting rises afterward.','Program change records; incident and near-miss trends','Program audit','Replaces v1 "Shapes safety practices" and administrative drift.'],
# Sensor networks FC-C01
['FCA-SENS-1','FC-C01','Foundational','Installs and services a field sensor (logger, sonde, acoustic recorder, camera trap, air sensor) to protocol: correct height, depth or orientation; secure mounting; complete metadata (location, clock sync, settings); functional test before leaving.','Deployment form; first-service data check showing valid data','Observed deployment plus data check at first service',''],
['FCA-SENS-2','FC-C01','Intermediate','Diagnoses data problems in the field (drift, fouling, power, animal damage, theft, siting bias) and corrects them; runs side-by-side checks against a reference instrument or manual measurement.','Service log; drift corrections; reference comparison data','Season log review plus data completeness and accuracy statistics',''],
['FCA-SENS-3','FC-C01','Advanced','Designs a network layout and service schedule that meets data-completeness targets under access, weather and budget limits, with planned redundancy and replacement.','Network design; achieved completeness','Portfolio plus outcome review',''],
['FCA-SENS-4','FC-C01','Expert','Sets field operation standards for sensor networks across programs (siting, service, QA) and resolves cross-program inconsistencies.','Standards documents; inter-program comparison','Peer review',''],
# Ground truth FC-C02
['FCA-GT-1','FC-C02','Foundational','Reaches pre-selected validation points, records the attribute with the reference protocol and photographs site conditions, without seeing the product\'s predicted value.','Reference data sheets; evidence that predictions were withheld','QA re-check of a sample of points by a second observer','Blindness protects the reference data.'],
['FCA-GT-2','FC-C02','Intermediate','At each mismatch between product and field, identifies the likely cause (timing, mixed pixels, hidden understory, class definition, location error) and codes it.','Annotated mismatch table','Assessor review of a sample with photos or site revisit',''],
['FCA-GT-3','FC-C02','Advanced','Designs the validation sample with an analyst (stratification, size, access limits), reports agreement with uncertainty and explains the limits to users.','Validation plan and report','Joint FC/DC review',''],
['FCA-GT-4','FC-C02','Expert','Defines field reference standards for a product line and decides from field evidence when a product is fit for a management or regulatory use.','Acceptance criteria; documented fitness-for-use decisions','Technical peer review','Pairs with v1 7.2.1 desk validation (DC).'],
# Automated field systems FC-C14
['FCA-UAS-1','FC-C14','Foundational','Plans and flies a routine mission within regulation and agency policy: airspace check, pre-flight inspection, weather and site hazards, crew briefing, safe launch and recovery, complete flight log.','Flight logs; check-ride record','Practical check ride with an evaluator','Part 107 or agency pilot card is a credential input.'],
['FCA-UAS-2','FC-C14','Intermediate','Handles abnormal events (lost link, low battery, aircraft or wildlife intrusion, GPS degradation) with the correct procedure; coordinates with air operations on an incident; collects data that meets accuracy checks (e.g., ground control check points).','Scenario performance on check ride; data QA results','Scenario-based check ride; incident task book where applicable',''],
['FCA-UAS-3','FC-C14','Advanced','Plans and supervises multi-aircraft, beyond-visual-line-of-sight or UAS ignition operations; makes abort or continue calls; keeps airworthiness records.','Operations plans; supervisor evaluation; maintenance records','Position qualification; operational audit','Part 108 places these duties on an operations supervisor.'],
['FCA-UAS-4','FC-C14','Expert','Builds an organization\'s UAS training, evaluation and safety-management processes; investigates incidents; program passes agency or regulator audit.','Safety management documentation; audit results; incident reports','External audit','Under Part 108 accountability is organizational.'],
# Crew leadership FC-C20
['FCA-LEAD-1','FC-C20','Foundational','Explains to a newer peer the field cues behind a call (why this is a gully head, why this plant is not its look-alike) in terms the peer can then apply.','Peer can apply the cue on the next instance (observed)','Observed teach-back in the field','Making tacit cues explicit is learnable early.'],
['FCA-LEAD-2','FC-C20','Intermediate','Leads a small crew through a field day: matches tasks to skill, checks novice work early and often, and makes cues explicit; crew members\' QA agreement improves over the season.','Crew QA agreement trend; observed field day','QA data review plus observation',''],
['FCA-LEAD-3','FC-C20','Advanced','Designs a season plan of graduated exposure for novices (demonstrate, do with check, do alone) and signs off readiness for independent work against observable criteria.','Training plan; sign-off records; QA of independent work','Portfolio and outcome review','Directly addresses entry-path loss.'],
['FCA-LEAD-4','FC-C20','Expert','Builds a cross-organization mentoring, rotation or apprenticeship structure through which field judgment transfers, with outcome evidence (QA agreement, retention, progression).','Program records; outcome data','Program evaluation (with CM, LC)',''],
]
ok=('Foundational','Intermediate','Advanced','Expert')
with open(OUT,'w',newline='',encoding='utf-8') as f:
    w=csv.writer(f); w.writerow(H)
    ids=set()
    for r in R:
        assert len(r)==len(H), r[0]; assert r[2] in ok; assert r[0] not in ids; ids.add(r[0])
        w.writerow(r)
comps={c for r in R for c in r[1].split('|')}
print(len(R),'anchors', len({r[1].split('|')[0] for r in R}),'primary competencies')
